# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: intake
def intake(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs, offset=4):
    return [v + offset for v in xs]

# region: render
def render(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(emit(render(fold(intake(shape(raw))))))

