        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'total': 18, 'label': 'BETA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'total': 14, 'label': 'BETA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'total': 0, 'label': 'EMPTY'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 2, 'total': 32, 'label': 'BETA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 4, 'label': 'BETA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 40, 'label': 'BETA'})
